func didFailTask(_ task: URLSessionTask, earlyWithError error: AFError) {
	dispatchPrecondition(condition: .onQueue(underlyingQueue))

	self.error = error

	// Task will still complete, so didCompleteTask(_:with:) will handle retry.
	eventMonitor?.request(self, didFailTask: task, earlyWithError: error)
}

func cancelRequestsForSessionInvalidation(with error: (any Error)?) {
	dispatchPrecondition(condition: .onQueue(rootQueue))

	let requests = mutableState.read(\.activeRequests)
	for request in requests where !request.isFinished {
		request.finish(error: .sessionInvalidated(error: error))
	}
}

func request<R: Request>(for task: URLSessionTask, as type: R.Type) -> R? {
