static func boundaryData(forBoundaryType boundaryType: BoundaryType, boundary: String) -> Data {
	let boundaryText = switch boundaryType {
	case .initial:
		"--\(boundary)\(EncodingCharacters.crlf)"
	case .encapsulated:
		"\(EncodingCharacters.crlf)--\(boundary)\(EncodingCharacters.crlf)"
	case .final:
		"\(EncodingCharacters.crlf)--\(boundary)--\(EncodingCharacters.crlf)"
	}

	return Data(boundaryText.utf8)
}

static func boundaryData(boundaryType: BoundaryType, boundaryKey: String) -> Data {
	Data(BoundaryGenerator.boundary(forBoundaryType: boundaryType,
									boundaryKey: boundaryKey).utf8)
}

